/* From Uiverse.io by ClawHack1 - Tags: loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  position: relative;
}

.__UIV_SCOPE__ .loader:before {
  content: "";
  position: absolute;
  top: -10px;
  left: -10px;
  right: -10px;
  bottom: -10px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .loader-inner {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.__UIV_SCOPE__ .loader-block {
  display: inline-block;
  width: 10px;
  height: 10px;
  margin: 2px;
  background-color: #fff;
  box-shadow: 0 0 20px #fff;
  animation: loader_562 1.2s cubic-bezier(0.5, 0, 0.5, 1) infinite;
}

.__UIV_SCOPE__ .loader-block:nth-child(1) {
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .loader-block:nth-child(2) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .loader-block:nth-child(3) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader-block:nth-child(4) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .loader-block:nth-child(5) {
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .loader-block:nth-child(6) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader-block:nth-child(7) {
  animation-delay: 0.7s;
}

.__UIV_SCOPE__ .loader-block:nth-child(8) {
  animation-delay: 0.8s;
}

@keyframes loader_562 {
  0% {
    transform: scale(1);
    box-shadow: 0 0 20px rgba(255, 255, 255, 0.5);
  }

  20% {
    transform: scale(1, 2.5);
    box-shadow: 0 0 50px rgba(255, 255, 255, 0.7);
  }

  40% {
    transform: scale(1);
    box-shadow: 0 0 20px rgba(255, 255, 255, 0.5);
  }
}
